// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNumber, uint256 blockTime) public {
        vm.assume(blockNumber > 0);
        vm.assume(blockTime > 0);
        vm.roll(blockNumber);
        vm.warp(blockTime);
        address sender = makeAddr("sender");
        vm.deal(sender, 10 ether);
        uint256 balanceBefore = address(c).balance;
        vm.prank(sender);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok);
        if (blockNumber % 15 == 0) {
            assertEq(address(c).balance, 0);
        } else {
            assertEq(address(c).balance, balanceBefore + 10 ether);
        }
    }
}
